@Test
public void testHoodiePaths() throws IOException {
    // Create a temp folder as the base path
    String basePath = HoodieTestUtils.initializeTempHoodieBasePath();
    HoodieTestUtils.createCommitFiles(basePath, "001", "002");
    HoodieTestUtils.createInflightCommitFiles(basePath, "003");
    HoodieTestUtils.createDataFile(basePath, "2017/01/01", "001", "f1");
    HoodieTestUtils.createDataFile(basePath, "2017/01/01", "001", "f2");
    HoodieTestUtils.createDataFile(basePath, "2017/01/01", "001", "f3");
    HoodieTestUtils.createDataFile(basePath, "2017/01/01", "002", "f2");
    HoodieTestUtils.createDataFile(basePath, "2017/01/01", "003", "f3");
    HoodieROTablePathFilter pathFilter = new HoodieROTablePathFilter();
    Path partitionPath = new Path("file://" + basePath + File.separator + "2017/01/01");
    assertTrue("Directories should be accepted", pathFilter.accept(partitionPath));
    assertTrue(pathFilter.accept(new Path("file://" + HoodieTestUtils.getDataFilePath(basePath, "2017/01/01", "001", "f1"))));
    assertFalse(pathFilter.accept(new Path("file://" + HoodieTestUtils.getDataFilePath(basePath, "2017/01/01", "001", "f2"))));
    assertTrue(pathFilter.accept(new Path("file://" + HoodieTestUtils.getDataFilePath(basePath, "2017/01/01", "001", "f3"))));
    assertTrue(pathFilter.accept(new Path("file://" + HoodieTestUtils.getDataFilePath(basePath, "2017/01/01", "002", "f2"))));
    assertFalse(pathFilter.accept(new Path("file://" + HoodieTestUtils.getDataFilePath(basePath, "2017/01/01", "003", "f3"))));
}

@Test
public void testNonHoodiePaths() throws IOException {
    TemporaryFolder folder = new TemporaryFolder();
    folder.create();
    String basePath = folder.getRoot().getAbsolutePath();
    HoodieROTablePathFilter pathFilter = new HoodieROTablePathFilter();
    String path = basePath + File.separator + "nonhoodiefolder";
    new File(path).mkdirs();
    assertTrue(pathFilter.accept(new Path("file://" + path)));
    path = basePath + File.separator + "nonhoodiefolder/somefile";
    new File(path).createNewFile();
    assertTrue(pathFilter.accept(new Path("file://" + path)));
}

@Test
public void testSchemaDiff() throws IOException, InitializationError {
    HoodieDatasetReference metadata = TestUtil.createDataset("test1", "/tmp/hdfs/DatasetSchemaTest/testSchema/", 5, "/nation.schema");
    HoodieHiveSchemaSyncTask schema = HoodieHiveSchemaSyncTask.newBuilder().withReference(metadata).withConfiguration(TestUtil.hDroneConfiguration).build();
    SchemaDifference diff = schema.getSchemaDifference();
    assertEquals("There should be 4 columns to be added", 4, diff.getAddColumnTypes().size());
    assertEquals("No update columns expected", 0, diff.getUpdateColumnTypes().size());
    assertEquals("No delete columns expected", 0, diff.getDeleteColumns().size());
    schema.sync();
    schema = HoodieHiveSchemaSyncTask.newBuilder().withReference(metadata).withConfiguration(TestUtil.hDroneConfiguration).build();
    diff = schema.getSchemaDifference();
    assertEquals("After sync, there should not be any new columns to add", 0, diff.getAddColumnTypes().size());
    assertEquals("After sync, there should not be any new columns to update", 0, diff.getUpdateColumnTypes().size());
    assertEquals("After sync, there should not be any new columns to delete", 0, diff.getDeleteColumns().size());
}

@Test
public void testSchemaEvolution() throws IOException, InitializationError {
    int initialPartitionsCount = 5;
    HoodieDatasetReference metadata = TestUtil.createDataset("test1", "/tmp/hdfs/DatasetSchemaTest/testSchema/", initialPartitionsCount, "/nation.schema");
    HoodieHiveSchemaSyncTask schema = HoodieHiveSchemaSyncTask.newBuilder().withReference(metadata).withConfiguration(TestUtil.hDroneConfiguration).build();
    schema.sync();
    schema = HoodieHiveSchemaSyncTask.newBuilder().withReference(metadata).withConfiguration(TestUtil.hDroneConfiguration).build();
    SchemaDifference diff = schema.getSchemaDifference();
    assertEquals("After sync, diff should be empty", true, diff.isEmpty());
    int newSchemaversion = 2;
    int newPartitionsCount = 2;
    TestUtil.evolveDataset(metadata, newPartitionsCount, "/nation_evolved.schema", DateTime.now().getMillis(), newSchemaversion);
    schema = HoodieHiveSchemaSyncTask.newBuilder().withReference(metadata).withConfiguration(TestUtil.hDroneConfiguration).build();
    diff = schema.getSchemaDifference();
    assertEquals("Schema has evolved, there should be a diff", false, diff.isEmpty());
    assertEquals("Schema has evolved, there should be 1 column to add", 1, diff.getAddColumnTypes().size());
    assertEquals("Schema has evolved, there should be 1 column to update", 1, diff.getUpdateColumnTypes().size());
    assertEquals(0, diff.getDeleteColumns().size());
}

/**
 * Testing converting array types to Hive field declaration strings,
 * according to the Parquet-113 spec:
 * https://github.com/apache/parquet-format/blob/master/LogicalTypes.md#lists
 */
@Test
public void testSchemaConvertArray() throws IOException {
    // Testing the 3-level annotation structure
    MessageType schema = parquet.schema.Types.buildMessage().optionalGroup().as(parquet.schema.OriginalType.LIST).repeatedGroup().optional(PrimitiveType.PrimitiveTypeName.INT32).named("element").named("list").named("int_list").named("ArrayOfInts");
    String schemaString = SchemaUtil.generateSchemaString(schema);
    assertEquals("`int_list` ARRAY< int>", schemaString);
    // A array of arrays
    schema = parquet.schema.Types.buildMessage().optionalGroup().as(parquet.schema.OriginalType.LIST).repeatedGroup().requiredGroup().as(OriginalType.LIST).repeatedGroup().required(PrimitiveType.PrimitiveTypeName.INT32).named("element").named("list").named("element").named("list").named("int_list_list").named("ArrayOfArrayOfInts");
    schemaString = SchemaUtil.generateSchemaString(schema);
    assertEquals("`int_list_list` ARRAY< ARRAY< int>>", schemaString);
    // A list of integers
    schema = parquet.schema.Types.buildMessage().optionalGroup().as(parquet.schema.OriginalType.LIST).repeated(PrimitiveType.PrimitiveTypeName.INT32).named("element").named("int_list").named("ArrayOfInts");
    schemaString = SchemaUtil.generateSchemaString(schema);
    assertEquals("`int_list` ARRAY< int>", schemaString);
    // A list of structs with two fields
    schema = parquet.schema.Types.buildMessage().optionalGroup().as(parquet.schema.OriginalType.LIST).repeatedGroup().required(PrimitiveType.PrimitiveTypeName.BINARY).named("str").required(PrimitiveType.PrimitiveTypeName.INT32).named("num").named("element").named("tuple_list").named("ArrayOfTuples");
    schemaString = SchemaUtil.generateSchemaString(schema);
    assertEquals("`tuple_list` ARRAY< STRUCT< `str` : binary, `num` : int>>", schemaString);
    // A list of structs with a single field
    // For this case, since the inner group name is "array", we treat the
    // element type as a one-element struct.
    schema = parquet.schema.Types.buildMessage().optionalGroup().as(parquet.schema.OriginalType.LIST).repeatedGroup().required(PrimitiveType.PrimitiveTypeName.BINARY).named("str").named("array").named("one_tuple_list").named("ArrayOfOneTuples");
    schemaString = SchemaUtil.generateSchemaString(schema);
    assertEquals("`one_tuple_list` ARRAY< STRUCT< `str` : binary>>", schemaString);
    // A list of structs with a single field
    // For this case, since the inner group name ends with "_tuple", we also treat the
    // element type as a one-element struct.
    schema = parquet.schema.Types.buildMessage().optionalGroup().as(parquet.schema.OriginalType.LIST).repeatedGroup().required(PrimitiveType.PrimitiveTypeName.BINARY).named("str").named("one_tuple_list_tuple").named("one_tuple_list").named("ArrayOfOneTuples2");
    schemaString = SchemaUtil.generateSchemaString(schema);
    assertEquals("`one_tuple_list` ARRAY< STRUCT< `str` : binary>>", schemaString);
    // A list of structs with a single field
    // Unlike the above two cases, for this the element type is the type of the
    // only field in the struct.
    schema = parquet.schema.Types.buildMessage().optionalGroup().as(parquet.schema.OriginalType.LIST).repeatedGroup().required(PrimitiveType.PrimitiveTypeName.BINARY).named("str").named("one_tuple_list").named("one_tuple_list").named("ArrayOfOneTuples3");
    schemaString = SchemaUtil.generateSchemaString(schema);
    assertEquals("`one_tuple_list` ARRAY< binary>", schemaString);
    // A list of maps
    schema = parquet.schema.Types.buildMessage().optionalGroup().as(parquet.schema.OriginalType.LIST).repeatedGroup().as(OriginalType.MAP).repeatedGroup().as(OriginalType.MAP_KEY_VALUE).required(PrimitiveType.PrimitiveTypeName.BINARY).as(OriginalType.UTF8).named("string_key").required(PrimitiveType.PrimitiveTypeName.INT32).named("int_value").named("key_value").named("array").named("map_list").named("ArrayOfMaps");
    schemaString = SchemaUtil.generateSchemaString(schema);
    assertEquals("`map_list` ARRAY< MAP< string, int>>", schemaString);
}

@Test
public void testDatasetCreation() throws IOException, InitializationError {
    HoodieDatasetReference metadata = TestUtil.createDataset("test1", "/tmp/hdfs/DatasetSchemaTest/testSchema/", 5, "/nation.schema");
    HoodieHiveDatasetSyncTask dataset = HoodieHiveDatasetSyncTask.newBuilder().withReference(metadata).withConfiguration(TestUtil.hDroneConfiguration).build();
    assertEquals("There should be 5 new partitions", 5, dataset.getNewPartitions().size());
    assertEquals("There should not be any changed partitions", 0, dataset.getChangedPartitions().size());
    assertFalse("Table should not exist", hiveClient.checkTableExists(metadata));
    dataset.sync();
    dataset = HoodieHiveDatasetSyncTask.newBuilder().withReference(metadata).withConfiguration(TestUtil.hDroneConfiguration).build();
    assertTrue("Table should exist after sync", hiveClient.checkTableExists(metadata));
    assertEquals("After sync, There should not be any new partitions to sync", 0, dataset.getNewPartitions().size());
    assertEquals("After sync, There should not be any modified partitions to sync", 0, dataset.getChangedPartitions().size());
    assertEquals("Table Schema should have 5 fields", 5, hiveClient.getTableSchema(metadata).size());
}

@Test
public void testDatasetEvolution() throws IOException, InitializationError {
    int initialPartitionsCount = 5;
    HoodieDatasetReference metadata = TestUtil.createDataset("test1", "/tmp/hdfs/DatasetSchemaTest/testSchema/", initialPartitionsCount, "/nation.schema");
    HoodieHiveDatasetSyncTask dataset = HoodieHiveDatasetSyncTask.newBuilder().withReference(metadata).withConfiguration(TestUtil.hDroneConfiguration).build();
    dataset.sync();
    dataset = HoodieHiveDatasetSyncTask.newBuilder(dataset).build();
    int newSchemaversion = 2;
    int newPartitionsCount = 2;
    TestUtil.evolveDataset(metadata, newPartitionsCount, "/nation_evolved.schema", DateTime.now().getMillis(), newSchemaversion);
    dataset = HoodieHiveDatasetSyncTask.newBuilder(dataset).build();
    assertEquals("There should be " + newPartitionsCount + " partitions to be added", newPartitionsCount, dataset.getNewPartitions().size());
    dataset.sync();
    dataset = HoodieHiveDatasetSyncTask.newBuilder(dataset).build();
    MessageType newDatasetSchema = dataset.getSchemaSyncTask().getStorageSchema();
    MessageType expectedSchema = TestUtil.readSchema("/nation_evolved.schema");
    assertEquals("Table schema should be evolved schema", expectedSchema, newDatasetSchema);
    assertEquals("Table schema should have 6 fields", 6, hiveClient.getTableSchema(metadata).size());
    assertEquals("Valid Evolution should be reflected", "BIGINT", hiveClient.getTableSchema(metadata).get("region_key"));
}

